const scriptFiles = (await fs.readdir(S).catch(()=>[])).filter(f=>/^_(os|dm|vf|overseas|domestic|verify)/i.test(f));
const agents = await tools.list_agents({});
const tasks = await tools.team_task_list({});
return {
  reportsSoFar: reports,
  newScripts: scriptFiles.slice(0,15),
  agents: agents.map(a=>String(a.target)+"|"+String(a.status)),
